module min_vertices_finder (input clk, input rst_n, input start, output reg [3:0] result, output reg done, input [3:0] N, input [3:0] K, input [7:0][63:0] vertices, input [7:0][63:0] points); reg [3:0] n_reg; reg [3:0] k_reg; reg [7:0][63:0] vertices_reg [7:0]; reg [7:0][63:0] points_reg [7:0]; reg [7:0] subset_counter; reg [3:0] current_min; reg [3:0] result; reg done_flag; reg [1:0] state; parameter IDLE = 2'd0; parameter SEARCHING = 2'd1; parameter DONE = 2'd2; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; n_reg <= 4'b0; k_reg <= 4'b0; vertices_reg <= 8'b0; points_reg <= 8'b0; subset_counter <= 8'b0; current_min <= 4'b0; result <= 4'b0; done_flag <= 1'b0; end else begin if (state == IDLE) begin if (start) begin n_reg <= N; k_reg <= K; vertices_reg <= vertices; points_reg <= points; subset_counter <= 8'b0; current_min <= N; state <= SEARCHING; end end else if (state == SEARCHING) begin if (subset_counter == (1 << n_reg) - 1) begin state <= DONE; done_flag <= 1'b1; result <= current_min; end else begin subset_counter <= subset_counter + 1; end end end end end assign result = current_min; assign done = done_flag; endmodule